            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE SCREENING PARADOX</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Testing people who feel fine</text><rect x=\"80\" y=\"180\" width=\"440\" height=\"300\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"300\" y=\"240\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">POSSIBLE BENEFITS</text><text x=\"300\" y=\"300\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Catch disease early</text><text x=\"300\" y=\"345\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Easier treatment</text><text x=\"300\" y=\"390\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Fewer deaths</text><rect x=\"580\" y=\"180\" width=\"440\" height=\"300\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"800\" y=\"240\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">POSSIBLE HARMS</text><text x=\"800\" y=\"300\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">False alarms</text><text x=\"800\" y=\"345\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Extra biopsies</text><text x=\"800\" y=\"390\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Overdiagnosis</text><rect x=\"200\" y=\"560\" width=\"700\" height=\"100\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"605\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">A good test is one where benefits</text><text x=\"550\" y=\"640\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">clearly outweigh harms</text></svg>",
