            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"120\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"180\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">CERVICAL SCREENING AT 35</text><text x=\"550\" y=\"225\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Three valid options exist after 30</text><text x=\"550\" y=\"265\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Which interval matches HPV alone?</text><rect x=\"80\" y=\"360\" width=\"300\" height=\"120\" rx=\"20\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"230\" y=\"430\" text-anchor=\"middle\" fill=\"#ec4899\" font-size=\"22\">Pap: 3 yr</text><rect x=\"400\" y=\"360\" width=\"300\" height=\"120\" rx=\"20\" fill=\"rgba(139,92,246,0.15)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"430\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-size=\"22\">HPV: ?</text><rect x=\"720\" y=\"360\" width=\"300\" height=\"120\" rx=\"20\" fill=\"rgba(20,184,166,0.15)\" stroke=\"#14b8a6\" stroke-width=\"2\"/><text x=\"870\" y=\"430\" text-anchor=\"middle\" fill=\"#14b8a6\" font-size=\"22\">Co-test: 5 yr</text></svg>",
