            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"140\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"200\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">THYROID SCREENING</text><text x=\"550\" y=\"250\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Diagnoses up ~15x, deaths flat</text><text x=\"550\" y=\"295\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">USPSTF 2017: Grade D</text><rect x=\"150\" y=\"400\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"550\" y=\"472\" text-anchor=\"middle\" fill=\"#ef4444\" font-size=\"22\">Finding more is not saving more</text></svg>",
